import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"32、【恆】 巽下震上","description":"周易尚氏學 - 32、【恆】 巽下震上","frontmatter":{"title":"32、【恆】 巽下震上","description":"周易尚氏學 - 32、【恆】 巽下震上"},"headers":[],"relativePath":"classics/shangshi/037.md","filePath":"classics/shangshi/037.md"}'),s={name:"classics/shangshi/037.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_32、【恆】-巽下震上" tabindex="-1">32、【恆】 巽下震上 <a class="header-anchor" href="#_32、【恆】-巽下震上" aria-label="Permalink to “32、【恆】 巽下震上”">​</a></h1><p>鹹男下女。男求女。得婚姻之正。夫婦之道既立。則長男在前。長女在後。夫倡婦隨。終身以之。故受之以恆。恆常也。久也。卦六爻皆有應。故亨利貞。易林大畜之未濟雲。乾坤利貞。乳生六子。利貞者和合也。二五應初承重陽。四臨重陰。故曰利有攸往。虞翻謂終變成益者是也。</p><p>彖曰。恆。久也。剛上而柔下。雷風相與。巽而動。剛柔皆應。恆。恆亨無咎利貞。久於其道也。天地之道。恆久而不巳也。利有攸往。終則有始也。日月得天而能久照。四時變化而能大成。聖人久於其道而天下化成。觀其所恆。而天地萬物之情可見矣。</p><p>泰初四相上下成震巽。故曰剛上而柔下。震巽相反覆。乾坤者震巽之終。震巽者乾坤之始。故曰終則有始。蠱先甲三日。後甲三日。終則有始。與此理同也。夫婦者天地也。天地之道。循環往來。恆久不已。乾為日。兌為月。日月久照。恆也。震為春。巽為夏。兌秋。乾冬。四時反覆。無有窮期。恆也。乾為聖人。震巽為草木。故曰萬物之情。</p><p>象曰。雷風。恆。君子以立不易方。</p><p>雷風同聲相應。可常可久。立而易方。則不恆矣。故此卦六爻皆有應。而爻辭皆不取。論語有勇知方。注。方義也。立不易方。即蹈義而行。無或違也。</p><p>初六。浚恆。貞兇。無攸利。</p><p>浚深也。虞翻雲。乾初為淵故深。深謂陽。乃泰初陽上居四。四陰下居初。雖皆失位。而仍有相求相交之象。故曰浚恆。乃四陽為二三所隔。不能應初。若初則可應四也。惟初遠應四。則有近不承陽之嫌。為二三所忌。故曰貞兇。無攸利。貞卜問。巽為利也。</p><h3 id="象曰。浚恆之兇。始求深也。" tabindex="-1">象曰。浚恆之兇。始求深也。 <a class="header-anchor" href="#象曰。浚恆之兇。始求深也。" aria-label="Permalink to “象曰。浚恆之兇。始求深也。”">​</a></h3><p>又在初稱始。宜靜不宜動。況陰居初失位。尤不宜動。以違恆久之義。乃初六求與四陽交。不知二三之有厲。故曰浚恆之兇。始求深也。言兇之故在初六求與四交也。焦氏易林泰之恆雲。蔡倏適楚。流連江濱。逾日曆月。思其後君。糞為草莽。故為蔡。叢木為楚。故震為楚。言初求四。故曰蔡侯適楚。乾為江海。初在乾下。故曰流連江濱。乾為日兌為月。初前臨乾兌。故曰逾日曆月。初求交四。震為君。故曰思其後君。林詞專釋此爻與四之關係。而曰思其後君。釋求深之義。尤為明白。故本焦義以為詁。</p><p>九二。悔亡。</p><p>二不當位。前臨重陽。宜有悔矣。然得中位。進雖不利。中正自守，亦無悔也。</p><h3 id="象曰。九二悔亡。能久中也。" tabindex="-1">象曰。九二悔亡。能久中也。 <a class="header-anchor" href="#象曰。九二悔亡。能久中也。" aria-label="Permalink to “象曰。九二悔亡。能久中也。”">​</a></h3><p>乾為久。為三四所隔。不能應五。故久於中。卦以恆為義。久中故悔亡。</p><p>九三。不恆其德。或承之羞。貞吝。</p><p>乾為德。三承乘皆陽。宜靜不宜動。倘亟於應上。而四或害之。則羞吝生矣。故貞吝也。又三居巽上。下橈。進退不定。亦不恆之一因也。</p><h3 id="象曰。不恆其德。無所容也。" tabindex="-1">象曰。不恆其德。無所容也。 <a class="header-anchor" href="#象曰。不恆其德。無所容也。" aria-label="Permalink to “象曰。不恆其德。無所容也。”">​</a></h3><p>乾為德。承乘皆陽。進退有阻。故曰無所容。</p><p>九四。田無禽。</p><p>震為田獵。禽獲也。下應初。三二遇敵。受阻。故無禽。按四前臨重陰。例之豫四。大壯解豐。四爻皆吉。茲獨不吉者。卦以恆久貞定為義。故不取利往也。</p><h3 id="象曰。大非其位。安得禽也。" tabindex="-1">象曰。大非其位。安得禽也。 <a class="header-anchor" href="#象曰。大非其位。安得禽也。" aria-label="Permalink to “象曰。大非其位。安得禽也。”">​</a></h3><p>乾為久。乾四失位。故曰久非其位。</p><p>六五。恆其德。貞婦人吉。夫子兇。</p><p>二五為夫婦。乾為德。六五下遇重陽。而正應在九二。通利極矣。陰得陽應。終身順承。故貞婦人吉。乾為夫。大過九二。老夫得女妻是也。故夫子謂九二。六五者九二之婦。本為正應。然二著應五而從婦。則三四遇敵。橫犯災難。故曰夫子兇。大畜初九曰。不犯災。需初九曰。不犯難行。二卦初九。皆有正應。而皆二三得敵。故日災難。茲與之同。</p><h3 id="象曰。婦人貞吉。從一而終也。夫子制義。從婦兇也。" tabindex="-1">象曰。婦人貞吉。從一而終也。夫子制義。從婦兇也。 <a class="header-anchor" href="#象曰。婦人貞吉。從一而終也。夫子制義。從婦兇也。" aria-label="Permalink to “象曰。婦人貞吉。從一而終也。夫子制義。從婦兇也。”">​</a></h3><p>五應二。故曰從一而終。坤為義。乾制義者也。陽得陰應。本無足貴。況應之而犯災難乎。故曰從婦兇也。</p><p>上六。振恆。兇。</p><p>上六居動之極。故日振恆。振起也。卦以貞靜恆久為義。振則於恆德或違。故兇。</p><h3 id="象曰。振恆在上。大無功也。" tabindex="-1">象曰。振恆在上。大無功也。 <a class="header-anchor" href="#象曰。振恆在上。大無功也。" aria-label="Permalink to “象曰。振恆在上。大無功也。”">​</a></h3><p>交至上而窮。不宜動。大謂三。三欲應上。為四所隔。故曰大無功。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
